\begin{definition}
\label{def:2-8-extra-6}




For a smooth $F:M\to N$ and smooth charts $(U,\varphi)$, $(V,\psi)$, define $\widehat F=\psi\circ F\circ\varphi^{-1}$. It maps $\varphi(U\cap F^{-1}(V))$ into $\psi(V)$.
\end{definition}
